<script lang="ts">
	let username = $state(''); let code = $state(''); let password = $state(''); let notice = $state(''); let error = $state(''); let done = $state(false);
	async function recover() { error = ''; try { const r = await fetch('/api/auth/recovery', {method:'POST', headers:{'content-type':'application/json'}, body: JSON.stringify({username, code, password})}); const d = await r.json().catch(() => ({})); if (!r.ok) throw new Error(d.error || 'Unable to reset password'); done = true; notice = 'Password reset. You can sign in again.'; } catch (e) { error = e instanceof Error ? e.message : 'Unable to reset password'; } }
</script>
<svelte:head><title>Recover account | BidLadders</title></svelte:head>
<div class="profile-shell"><nav class="detail-nav"><a class="brand" href="/"><img class="brand-logo" src="/bid.svg" alt="" /><span>BidLadders</span></a><a class="back-link" href="/">← Sign in</a></nav><main class="profile-main"><header class="profile-heading"><div><p class="eyebrow">ACCOUNT RECOVERY</p><h1>Reset your password.</h1><p>Use the username and current authenticator code for the account.</p></div></header>{#if !done}<div class="profile-form"><div class="field"><label for="username">Username</label><input id="username" autocomplete="username" bind:value={username} /></div><div class="field"><label for="code">Authenticator code</label><input id="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" bind:value={code} /></div><div class="field"><label for="password">New password</label><input id="password" type="password" autocomplete="new-password" bind:value={password} placeholder="12+ chars, upper/lower/number" /></div><button class="button dark" onclick={recover}>Reset password</button></div>{/if}{#if notice}<div class="notice">{notice}</div>{/if}{#if error}<div class="error-banner">{error}</div>{/if}</main></div>
